/**
 * Creates the monthly, customer level, billing schedule for a customer.
 * The scheduler is keyed off of the customerId so that a customer only ever has a single billing schedule.
 */
private async createBillingSchedule({
    customerId,
    businessID,
    subject,
}: {
    customerId: string;
    businessID: string;
    subject?: string;
}) {
    CustomerService.logger.log(`Creating billing schedule for customer: ${customerId}`);
    return this.schedulerService.create({
        schedulerID: customerId,
        schedulerType: schedulerType.billing,
        schedulerStatus: SchedulerStatus.live,
        scheduleParameters: { customerId, businessID },
        rate: SupportedMeasurementFrequencies.monthly,
        subject,
        businessID,
    });
}

/**
 * Removes any pre-existing billing schedule for the customer and replaces it with a
 * customer level billing schedule. A missing schedule is not considered an error.
 */
private async replaceBillingSchedule({
    customerId,
    businessID,
    subject,
}: {
    customerId: string;
    businessID: string;
    subject?: string;
}) {
    try {
        await this.schedulerService.remove({ schedulerID: customerId, businessID, isBillingQueue: true });
    } catch (e) {
        if (e instanceof NotFoundException) {
            CustomerService.logger.log(`Scheduler for customer ${customerId} not found`);
        } else {
            throw e;
        }
    }
    return this.createBillingSchedule({ customerId, businessID, subject });
}

