describe('CustomerService', () => {
    let service: CustomerService;
    const businessID = 'myCoolCorp';
    const subject = 'auth0|1337';

    beforeEach(async () => {
        const module: TestingModule = await Test.createTestingModule({
            providers: [CustomerService],
            imports: [
                InfluxModule,
                forwardRef(() => SchedulerModule),
                forwardRef(() => PrivateAPIServicesModule),
                forwardRef(() => PrivateAPIOfferingModule),
                forwardRef(() => UsageModule),
            ],
        }).compile();

        service = module.get<CustomerService>(CustomerService);
        jest.spyOn(service.InfluxService, 'loadPoints').mockResolvedValue(undefined);
    });

    afterEach(() => {
        jest.restoreAllMocks();
    });

    it('should be defined', () => {
        expect(service).toBeDefined();
    });

    describe('create', () => {
        it('creates a monthly billing schedule for a customer with an offering', async () => {
            const schedulerSpy = jest
                .spyOn(service.schedulerService, 'create')
                .mockResolvedValue({ message: 'Cron expression added', data: [] });
            const offeringId = 'a6a0b1d2-0000-4000-8000-000000000001';
            const { customerId } = await service.create(
                { customerName: 'Wall Street Trading', email: '', paymentChannel: paymentChannel.manual, businessID, offeringId },
                subject
            );
            expect(schedulerSpy).toHaveBeenCalledWith({
                schedulerID: customerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: { customerId, businessID },
                rate: SupportedMeasurementFrequencies.monthly,
                subject,
                businessID,
            });
        });

        it('does not create a billing schedule for a customer without an offering', async () => {
            const schedulerSpy = jest.spyOn(service.schedulerService, 'create');
            await service.create(
                { customerName: 'Wall Street Trading', email: '', paymentChannel: paymentChannel.manual, businessID },
                subject
            );
            expect(schedulerSpy).not.toHaveBeenCalled();
        });
    });

    describe('update', () => {
        const customerId = 'b9459f53-054b-4437-8ecd-b6f8070344fc';
        const buildFindOne = (offeringId?: string) =>
            jest.spyOn(service, 'findOne').mockResolvedValue({
                // eslint-disable-next-line @typescript-eslint/ban-ts-comment
                //@ts-ignore
                data: [{ customerId, customerName: 'Wall Street Trading', paymentChannel: paymentChannel.manual, offeringId }],
                message: 'Found Customer',
            });

        it('replaces the billing schedule when a customer gains an offering', async () => {
            buildFindOne(undefined);
            const removeSpy = jest
                .spyOn(service.schedulerService, 'remove')
                .mockResolvedValue({ message: 'Deleted Schedule', data: [] });
            const createSpy = jest
                .spyOn(service.schedulerService, 'create')
                .mockResolvedValue({ message: 'Cron expression added', data: [] });
            const offeringId = 'a6a0b1d2-0000-4000-8000-000000000002';

            await service.update({ customerId, businessID, offeringId }, subject);

            expect(removeSpy).toHaveBeenCalledWith({ schedulerID: customerId, businessID, isBillingQueue: true });
            expect(createSpy).toHaveBeenCalledWith({
                schedulerID: customerId,
                schedulerType: schedulerType.billing,
                schedulerStatus: SchedulerStatus.live,
                scheduleParameters: { customerId, businessID },
                rate: SupportedMeasurementFrequencies.monthly,
                subject,
                businessID,
            });
        });

        it('does not fail when there is no previous billing schedule to remove', async () => {
            buildFindOne('a6a0b1d2-0000-4000-8000-000000000002');
            jest.spyOn(service.schedulerService, 'remove').mockRejectedValue(new NotFoundException('nope'));
            const createSpy = jest
                .spyOn(service.schedulerService, 'create')
                .mockResolvedValue({ message: 'Cron expression added', data: [] });

            await expect(
                service.update({ customerId, businessID, offeringId: 'a6a0b1d2-0000-4000-8000-000000000003' }, subject)
            ).resolves.toEqual({ message: 'Customer updated added', customerId });
            expect(createSpy).toHaveBeenCalled();
        });

        it('leaves the billing schedule alone when the offering does not change', async () => {
            const offeringId = 'a6a0b1d2-0000-4000-8000-000000000002';
            buildFindOne(offeringId);
            const removeSpy = jest.spyOn(service.schedulerService, 'remove');
            const createSpy = jest.spyOn(service.schedulerService, 'create');

            await service.update({ customerId, businessID, offeringId }, subject);

            expect(removeSpy).not.toHaveBeenCalled();
            expect(createSpy).not.toHaveBeenCalled();
        });
    });
});

